import type { ControlOptions, SetValueOptions } from '../types/control.types';
import { AbstractControl } from './abstract-control.class';

export class FormControl<T = unknown> extends AbstractControl<T> {
	public readonly initialValue: T;

	constructor(initialValue: T, options: ControlOptions<T> = {}) {
		super(initialValue, options);
		this.initialValue = initialValue;
		this.initializeAggregates();
		void this.runValidation();
	}

	public setValue(value: T, options?: SetValueOptions): void {
		if (this._ownDisabled()) return;

		this.value.set(value);

		// Programmatic setValue does not dirty the control (Angular semantics).
		// User input dirties via the form-control directive's input handler.
		if (options?.markAsPristine) {
			this._dirty.set(false);
		}

		// A programmatic write always revalidates. `updateOn` governs when the
		// VIEW writes to the model (see the formControl directive), not whether
		// application code that sets a value gets a validated control back.
		void this.runValidation();
	}

	public patchValue(value: Partial<T>, options?: SetValueOptions): void {
		const current = this.value();
		if (typeof current === 'object' && current !== null && !Array.isArray(current)) {
			this.setValue({ ...current, ...value } as T, options);
		} else {
			this.setValue(value as T, options);
		}
	}

	public reset(value?: T): void {
		this.value.set(value ?? this.initialValue);
		this._dirty.set(false);
		this._touched.set(false);
		// runValidation recomputes errors from the reset value, so an explicit
		// errors.set(null) here would just be overwritten.
		void this.runValidation();
	}

	public destroy(): void {
		if (this._destroyed) return;
		this._destroyed = true;
		this.destroySignals();
	}
}
