import { getAttributeDirective } from '../directives/functions/attribute-directive.functions';
import type { ITemplatePart, IArrayItem, IKeyedArrayItem, IEventHandlerWithOptions } from '../interfaces/itemplate-part.interface';
import type { ITemplateCache, IPartPath } from '../interfaces/itemplate-cache.interface';
import type { IDirectiveState } from '../interfaces/idirective-state.interface';
import type { RenderedContainer } from '../interfaces/irendered-container.interface';
import { isDirective } from '../directives/functions/is-directive.function';
import { disposeParts, disposeContainerParts, disposeDirectiveState } from '../functions/dispose.functions';
import { renderDetachedItem } from '../functions/render-detached.function';
import { clearBetween, moveRange, removeRange } from '../functions/marker-range.functions';
import { isDevMode, devWarn } from '../../devtools/dev-mode';

/** Structural view of a directive result, avoiding a circular type import. */
interface IDirectiveResultLike {
	type: string | symbol;
	render(container: Node, previousState?: unknown, name?: string): unknown;
}

// Unique marker for identifying dynamic positions
const MARKER = `m${Math.random().toString(36).slice(2, 9)}`;
const COMMENT_NODE_MARKER = `<!--${MARKER}-->`;
const ATTRIBUTE_MARKER_PREFIX = `__${MARKER}_`;
const ATTRIBUTE_MARKER_REGEX = new RegExp(`${ATTRIBUTE_MARKER_PREFIX}(\\d+)__`, 'g');

const createAttributeMarker = (index: number): string => `${ATTRIBUTE_MARKER_PREFIX}${index}__`;

const templateCache = new Map<string, ITemplateCache>();

/**
 * Where the parser cursor sits in the markup written so far.
 *
 * Without this, the attribute regexes ran against raw HTML with no notion of
 * tag boundaries, so `html`<p>Total=${n}</p>`` matched `Total=` as an attribute
 * name and rendered the marker as visible text — in production, silently.
 */
interface ITagState {
	/** Inside an unclosed `<tag …`. */
	inTag: boolean;
	/** The quote character delimiting the attribute value being written, if any. */
	quote: string | null;
}

/** Advance `state` over a literal chunk of template text. */
function scanTagState(text: string, state: ITagState): ITagState {
	let { inTag, quote } = state;

	for (let i = 0; i < text.length; i++) {
		const char = text[i];

		if (inTag) {
			if (quote) {
				if (char === quote) {
					quote = null;
				}
				continue;
			}
			if (char === '"' || char === "'") {
				quote = char;
				continue;
			}
			if (char === '>') {
				inTag = false;
			}
			continue;
		}

		if (char !== '<') {
			continue;
		}

		if (text.startsWith('<!--', i)) {
			const end = text.indexOf('-->', i + 4);
			if (end === -1) {
				// Unterminated comment: the rest of this chunk is comment text.
				return { inTag: false, quote: null };
			}
			i = end + 2;
			continue;
		}

		if (text.startsWith('</', i)) {
			const end = text.indexOf('>', i);
			if (end === -1) {
				return { inTag: true, quote: null };
			}
			i = end;
			continue;
		}

		// `<` followed by anything that cannot start a tag name is literal text.
		if (/[a-zA-Z]/.test(text[i + 1] ?? '')) {
			inTag = true;
		}
	}

	return { inTag, quote };
}

// Dev-mode warning (once per property name) for property bindings that assign
// raw HTML — .innerHTML=${...} looks like a normal bind but bypasses the safe
// text path entirely.
const warnedUnsafeProperties = new Set<string>();
function warnUnsafePropertyBinding(name: string): void {
	if (warnedUnsafeProperties.has(name)) return;
	if (!isDevMode()) return;
	warnedUnsafeProperties.add(name);
	console.warn(
		`[Melodic] Property binding ".${name}" assigns raw HTML and is an XSS hazard if the value is not fully trusted. ` +
			'Prefer text interpolation, or unsafeHTML() with sanitized content.'
	);
}

/**
 * Dev-mode advisory for unkeyed arrays that are actually churning DOM.
 *
 * Plain `${items.map(…)}` arrays are reused positionally and are perfectly fine
 * for the common case, so their mere existence is NOT warned about. This fires
 * only when positional reuse could not keep an item's nodes — several items
 * rebuilt in one update is the signature of a list whose entries shifted
 * position, which is exactly what `repeat()` solves. Once per part.
 */
function warnUnkeyedArrayChurn(state: { warnedChurn?: boolean }, recreated: number, total: number): void {
	if (state.warnedChurn || recreated < 2 || total < 2) return;
	if (!isDevMode()) return;
	state.warnedChurn = true;
	console.warn(
		`[Melodic] An interpolated array rebuilt ${recreated} of ${total} items on one update. ` +
			'Unkeyed arrays are reused by index, so entries that change position lose their DOM nodes ' +
			'(and with them focus, scroll position, and in-flight clicks). ' +
			'Use repeat(items, keyFn, template) to track items by identity instead.'
	);
}

/**
 * Dev-mode warning for an array where SOME items carry a key and others do not.
 * Keyed diffing requires every item to be keyed, so one unkeyed entry silently
 * demotes the whole array to positional reuse — effectively always a mistake.
 * Once per part.
 */
const warnedPartiallyKeyedParts = new WeakSet<ITemplatePart>();
function warnPartiallyKeyedArray(part: ITemplatePart, values: unknown[]): void {
	if (!isDevMode() || warnedPartiallyKeyedParts.has(part)) return;

	let keyed = 0;
	for (const value of values) {
		if (value && typeof value === 'object' && (value as { __keyed?: boolean }).__keyed === true) keyed++;
	}
	if (keyed === 0 || keyed === values.length) return;

	warnedPartiallyKeyedParts.add(part);
	console.warn(
		`[Melodic] An interpolated array mixes keyed and unkeyed items (${keyed} of ${values.length} keyed). ` +
			'Keyed diffing requires every item to carry a key, so this array falls back to index-based reuse. ' +
			'Key every item, or none.'
	);
}

// Matches any marker the parser injects for a binding: text-position comment
// markers, composite attribute-value markers, and pre-processed binding
// attributes (@/./:/? forms).
const ANY_MARKER_REGEX = new RegExp(`${COMMENT_NODE_MARKER}|${ATTRIBUTE_MARKER_PREFIX}\\d+__|__(?:event|prop|action|bool)-\\d+__`);

/** Human-readable snippet around an offending marker (markers shown as `${…}`). */
function describeSnippet(html: string, index: number): string {
	const start = Math.max(0, index - 40);
	const end = Math.min(html.length, index + 80);
	const snippet = html
		.slice(start, end)
		.replace(new RegExp(`${COMMENT_NODE_MARKER}|${ATTRIBUTE_MARKER_PREFIX}\\d+__|__(?:event|prop|action|bool)-\\d+__=""`, 'g'), '${…}')
		.replace(/\s+/g, ' ')
		.trim();
	return `${start > 0 ? '…' : ''}${snippet}${end < html.length ? '…' : ''}`;
}

function warnUnsupportedBinding(position: string, html: string, index: number): void {
	console.warn(
		`[Melodic] Template contains a binding in an unsupported position (${position}). ` +
			`The parser cannot track bindings here, so the value will not render or update. ` +
			`Offending template: ${describeSnippet(html, index)}`
	);
}

/**
 * Dev-mode diagnostics for bindings in positions the parser cannot handle:
 * raw-text element content (<textarea>, <title>), HTML comments, and tag-name
 * position. These silently misrender in production (backwards compat — never
 * throws); in dev the offending template snippet is reported via console.warn.
 * Runs once per template (getTemplate caches by template key).
 *
 * Returns true when at least one warning was emitted, so the caller can skip
 * the leaked-binding check below rather than reporting the same template twice.
 */
function warnUnsupportedBindingPositions(html: string): boolean {
	if (!isDevMode()) return false;

	let warned = false;
	const report = (position: string, index: number): void => {
		warned = true;
		warnUnsupportedBinding(position, html, index);
	};

	// 1) Bindings inside raw-text elements: their content is parsed as literal
	//    text, so comment markers never become comment nodes.
	const rawTextRegex = /<(textarea|title)(?:\s[^>]*)?>([\s\S]*?)<\/\1\s*>/gi;
	let rawTextMatch: RegExpExecArray | null;
	while ((rawTextMatch = rawTextRegex.exec(html)) !== null) {
		if (ANY_MARKER_REGEX.test(rawTextMatch[2])) {
			report(`inside <${rawTextMatch[1].toLowerCase()}> content`, rawTextMatch.index);
		}
	}

	// 2) Bindings in tag-name position: `<${tag}>` / `</${tag}>` put a comment
	//    marker directly after `<`.
	const tagNameIndex = html.search(new RegExp(`</?${COMMENT_NODE_MARKER}`));
	if (tagNameIndex !== -1) {
		report('tag-name position', tagNameIndex);
	}

	// 3) Bindings inside HTML comments: comments cannot nest, so the injected
	//    marker corrupts the comment and the binding is lost.
	let searchFrom = 0;
	for (;;) {
		const open = html.indexOf('<!--', searchFrom);
		if (open === -1) break;

		// The parser's own text-position marker is itself a comment — skip it.
		if (html.startsWith(COMMENT_NODE_MARKER, open)) {
			searchFrom = open + COMMENT_NODE_MARKER.length;
			continue;
		}

		const close = html.indexOf('-->', open + 4);
		const content = close === -1 ? html.slice(open + 4) : html.slice(open + 4, close);
		if (content.includes(MARKER) || /__(?:event|prop|action|bool)-\d+__/.test(content)) {
			report('inside an HTML comment', open);
		}
		searchFrom = close === -1 ? html.length : close + 3;
	}

	return warned;
}

/**
 * Dev-mode diagnostic for bindings that parsed but never anchored to a node in
 * the template DOM. Every interpolation should be claimed by exactly one part
 * path; one that isn't has had its marker swallowed — most often by an
 * unbalanced quote in an attribute value, which makes the HTML parser consume
 * the following markup (and any markers in it) as attribute text.
 *
 * The visible symptom is otherwise baffling: the binding silently never
 * renders, and the leaked marker can surface as a stray attribute name on an
 * unrelated element far from the real mistake.
 *
 * Never throws (matches the surrounding diagnostics — broken templates still
 * render in production). Runs once per template, on the parse path only, so
 * update renders pay nothing.
 */
function warnLeakedBindings(partPaths: IPartPath[], expressionCount: number, html: string): void {
	if (!isDevMode()) return;

	// A part path claims either a run of attribute-value indices (composite
	// bindings such as class="a ${x} b ${y}") or a single value index. Static
	// action attributes carry index -1 and consume no interpolation.
	const anchored = new Set<number>();
	for (const partPath of partPaths) {
		if (partPath.attributeIndices) {
			for (const index of partPath.attributeIndices) {
				anchored.add(index);
			}
		} else if (partPath.index >= 0) {
			anchored.add(partPath.index);
		}
	}

	const lost: number[] = [];
	for (let index = 0; index < expressionCount; index++) {
		if (!anchored.has(index)) {
			lost.push(index);
		}
	}

	if (lost.length === 0) return;

	// Point the snippet at the first lost binding's marker where we can still
	// find it; otherwise fall back to the head of the template.
	const markerIndex = html.indexOf(createAttributeMarker(lost[0]));

	console.warn(
		`[Melodic] Template part marker leaked: ${lost.length} binding${lost.length === 1 ? '' : 's'} ` +
			`(value index ${lost.join(', ')}) could not be anchored to the parsed template and will never render or update. ` +
			`The usual cause is an unbalanced quote in an attribute value, which swallows the markup that follows it. ` +
			`Offending template: ${describeSnippet(html, markerIndex === -1 ? 0 : markerIndex)}`
	);
}

/**
 * Extract listener options (capture/once/passive) from a `handleEvent`-object
 * binding value. Returns undefined when no option flag is present, so plain
 * handleEvent objects register exactly like plain functions.
 */
function extractListenerOptions(value: IEventHandlerWithOptions): AddEventListenerOptions | undefined {
	const { capture, once, passive } = value;
	if (capture === undefined && once === undefined && passive === undefined) {
		return undefined;
	}

	const options: AddEventListenerOptions = {};
	if (capture !== undefined) options.capture = capture;
	if (once !== undefined) options.once = once;
	if (passive !== undefined) options.passive = passive;
	return options;
}

/** Compare listener options by effective (boolean) value. */
function sameListenerOptions(a: AddEventListenerOptions | undefined, b: AddEventListenerOptions | undefined): boolean {
	return !!a?.capture === !!b?.capture && !!a?.once === !!b?.once && !!a?.passive === !!b?.passive;
}

// Cache template keys by TemplateStringsArray identity to avoid repeated string joins
const templateKeyCache = new WeakMap<TemplateStringsArray, string>();

/**
 * Get or create a cache key for the template strings array.
 * Uses WeakMap to cache by object identity, avoiding expensive string joins on repeated renders.
 */
function getTemplateKey(strings: TemplateStringsArray): string {
	let key = templateKeyCache.get(strings);
	if (key === undefined) {
		key = strings.join(MARKER);
		templateKeyCache.set(strings, key);
	}
	return key;
}

export class TemplateResult {
	public strings: TemplateStringsArray;
	public values: unknown[];

	constructor(strings: TemplateStringsArray, values: unknown[]) {
		this.strings = strings;
		this.values = values;
	}

	/**
	 * Structural identity of this template (derived from its tagged template
	 * literal). Two TemplateResults with the same key share DOM structure and
	 * can be updated in place; different keys require a rebuild.
	 */
	public get templateKey(): string {
		return getTemplateKey(this.strings);
	}

	/**
	 * Optimized render for single-use containers (like repeat items).
	 * Returns the rendered nodes directly.
	 */
	public renderOnce(container: DocumentFragment): Node[] {
		const target = container as RenderedContainer<DocumentFragment>;
		const templateKey = getTemplateKey(this.strings);
		const cache = this.getTemplate(templateKey);
		const clone = cache.element.content.cloneNode(true);
		const parts = this.prepareParts(clone, cache);

		this.commit(parts);
		target.appendChild(clone);

		target.__parts = parts;
		target.__templateKey = templateKey;

		return Array.from(target.childNodes);
	}

	public renderInto(container: Element | DocumentFragment): void {
		const target = container as RenderedContainer<Element | DocumentFragment>;
		const templateKey = getTemplateKey(this.strings);

		// First render - clone and prepare
		const existingKey = target.__templateKey;
		if (existingKey && existingKey !== templateKey) {
			// Structure changed — recursively dispose the old part tree before
			// the container is wiped and rebuilt.
			if (target.__parts) {
				disposeParts(target.__parts);
			}
			delete target.__parts;
		}

		if (!target.__parts) {
			// Template lookup only on the instantiation path — update renders
			// touch only the stored parts (and skip the LRU recency churn).
			const cache = this.getTemplate(templateKey);
			const clone = cache.element.content.cloneNode(true);
			const parts = this.prepareParts(clone, cache);

			target.__parts = parts;
			target.__templateKey = templateKey;

			// Commit values BEFORE appending to DOM so attributes are set
			// before connectedCallback fires on child custom elements
			this.commit(parts);

			target.textContent = '';
			target.appendChild(clone);
			return;
		}

		// Update values
		if (!target.__templateKey) {
			target.__templateKey = templateKey;
		}
		this.commit(target.__parts);
	}

	private getTemplate(key: string): ITemplateCache {
		let cached = templateCache.get(key);

		if (cached) {
			// LRU: refresh recency so eviction removes the least recently USED
			// template, not the least recently created one.
			templateCache.delete(key);
			templateCache.set(key, cached);
			return cached;
		}

		const parts: ITemplatePart[] = [];
		let html = this.strings[0];

		const attrPreProcessor = this.getAttributePreProcessor(parts);
		let activeAttributeName: string | null = null;
		let activeAttributeQuote: string | null = null;
		let tagState = scanTagState(html, { inTag: false, quote: null });

		for (let i = 1; i < this.strings.length; i++) {
			let s = this.strings[i];
			const valueIndex = i - 1;

			// A binding is an ATTRIBUTE binding only when the cursor is inside an
			// open tag. Everywhere else it is a text binding, however much the
			// surrounding characters look like `name=`.
			const match = tagState.inTag ? /([@.:?]?[\w:-]+)\s*=\s*["']?$/.exec(html) : null;

			// An attribute value may legitimately contain the OTHER quote character
			// (title="it's ${x}" / title='say "${x}"'), so each quote style is
			// matched only against its own delimiter. Matching both delimiters at
			// once would miss these and fall through to the text-position branch,
			// which injects a comment marker inside the attribute value — it then
			// leaks into the DOM as literal text and the binding never updates.
			// When both match, the later one is the attribute still left open.
			const doubleQuotedAttrMatch = tagState.inTag ? /([@.:?]?[\w:-]+)\s*=\s*(")([^"]*)$/.exec(html) : null;
			const singleQuotedAttrMatch = tagState.inTag ? /([@.:?]?[\w:-]+)\s*=\s*(')([^']*)$/.exec(html) : null;
			const quotedAttrMatch =
				doubleQuotedAttrMatch && singleQuotedAttrMatch
					? doubleQuotedAttrMatch.index >= singleQuotedAttrMatch.index
						? doubleQuotedAttrMatch
						: singleQuotedAttrMatch
					: (doubleQuotedAttrMatch ?? singleQuotedAttrMatch);
			let attrKey: string = '___';

			if (activeAttributeName) {
				html += createAttributeMarker(valueIndex);
			} else {
				const quotedName = quotedAttrMatch?.[1];
				const quotedPrefix = quotedName?.charAt(0);
				const hasSpecialPrefix = quotedPrefix !== undefined && Object.keys(attrPreProcessor).includes(quotedPrefix);

				if (quotedAttrMatch && !hasSpecialPrefix) {
					html += createAttributeMarker(valueIndex);
					activeAttributeName = quotedAttrMatch[1];
					activeAttributeQuote = quotedAttrMatch[2];
				} else {
					if (match) {
						attrKey = '__';
						const attrPrefix: string = match[1].charAt(0);

						if (Object.keys(attrPreProcessor).includes(attrPrefix)) {
							attrKey = attrPrefix;
						}
					}

					if (attrKey === '__' && match) {
						html += createAttributeMarker(valueIndex);
						activeAttributeName = match[1];
						const quoteMatch = /(["'])$/.exec(match[0]);
						activeAttributeQuote = quoteMatch ? quoteMatch[1] : null;
					} else {
						// A special binding written with quotes (`@click="${h}"`)
						// has its OPENING quote consumed by the pre-processor, which
						// emits a complete `__event-N__=""` attribute. The closing
						// quote at the head of the next chunk then leaked out as a
						// stray attribute literally named `"`.
						const consumedQuote = attrKey !== '___' && match ? (/(["'])$/.exec(match[0])?.[1] ?? null) : null;

						html = attrPreProcessor[attrKey](valueIndex, html, match ? match[1] : undefined, match);

						if (consumedQuote && s.startsWith(consumedQuote)) {
							s = s.slice(1);
						}
					}
				}
			}
			html += s;
			tagState = scanTagState(s, tagState);

			if (activeAttributeName) {
				if (activeAttributeQuote) {
					if (s.includes(activeAttributeQuote)) {
						activeAttributeName = null;
						activeAttributeQuote = null;
					}
				} else if (/[\s>]/.test(s)) {
					activeAttributeName = null;
					activeAttributeQuote = null;
				}
			}
		}

		const hasUnsupportedBinding = warnUnsupportedBindingPositions(html);

		// NOTE(security/Trusted Types): this innerHTML assignment only ever parses
		// developer-authored template strings — interpolated values are replaced
		// with inert markers BEFORE parsing and never reach the markup, so this is
		// not an injection sink for runtime data. Trusted Types support (wrapping
		// this parse in a policy so the engine works under a
		// `require-trusted-types-for 'script'` CSP) was considered and deferred:
		// it needs a policy-name contract with consumers and a fallback for
		// browsers without the API, for no XSS-surface reduction here.
		const element = document.createElement('template');
		element.innerHTML = html;

		// Pre-compute part paths by walking template DOM once
		const partPaths: IPartPath[] = [];
		let nodePartCursor = 0;

		// Build lookup for node parts by index order
		const nodeParts: ITemplatePart[] = [];
		const eventPartsByIndex = new Map<number, ITemplatePart>();
		const propertyPartsByIndex = new Map<number, ITemplatePart>();
		const actionPartsByIndex = new Map<number, ITemplatePart>();
		const booleanPartsByIndex = new Map<number, ITemplatePart>();

		for (const part of parts) {
			switch (part.type) {
				case 'event':
					eventPartsByIndex.set(part.index, part);
					break;
				case 'property':
					propertyPartsByIndex.set(part.index, part);
					break;
				case 'action':
					actionPartsByIndex.set(part.index, part);
					break;
				case 'boolean-attribute':
					booleanPartsByIndex.set(part.index, part);
					break;
				case 'node':
					nodeParts.push(part);
					break;
				default:
					break;
			}
		}

		// Walk template content once to record paths
		const walkTemplate = (node: Node, path: number[]) => {
			if (node.nodeType === Node.COMMENT_NODE) {
				const comment = node as Comment;
				if (comment.data === MARKER) {
					const part = nodeParts[nodePartCursor++];
					if (part) {
						partPaths.push({
							path: [...path],
							type: 'node',
							index: part.index
						});
					}
				}
			} else if (node.nodeType === Node.ELEMENT_NODE) {
				const el = node as Element;

				// Check attributes for markers
				for (let i = el.attributes.length - 1; i >= 0; i--) {
					const attr = el.attributes[i];

					if (attr.name.startsWith('__event-')) {
						const index = parseInt(attr.name.match(/__event-(\d+)__/)?.[1] || '0');
						const part = eventPartsByIndex.get(index);
						if (part) {
							partPaths.push({
								path: [...path],
								type: 'event',
								index: part.index,
								name: part.name
							});
						}
					} else if (attr.name.startsWith('__prop-')) {
						const index = parseInt(attr.name.match(/__prop-(\d+)__/)?.[1] || '0');
						const part = propertyPartsByIndex.get(index);
						if (part) {
							partPaths.push({
								path: [...path],
								type: 'property',
								index: part.index,
								name: part.name
							});
						}
					} else if (attr.name.startsWith('__action-')) {
						const index = parseInt(attr.name.match(/__action-(\d+)__/)?.[1] || '0');
						const part = actionPartsByIndex.get(index);
						if (part) {
							partPaths.push({
								path: [...path],
								type: 'action',
								index: part.index,
								name: part.name
							});
						}
					} else if (attr.name.startsWith('__bool-')) {
						const index = parseInt(attr.name.match(/__bool-(\d+)__/)?.[1] || '0');
						const part = booleanPartsByIndex.get(index);
						if (part) {
							partPaths.push({
								path: [...path],
								type: 'boolean-attribute',
								index: part.index,
								name: part.name
							});
						}
					} else if (attr.name.startsWith(':')) {
						// Static action directive
						partPaths.push({
							path: [...path],
							type: 'action',
							index: -1,
							name: attr.name.slice(1),
							staticValue: attr.value
						});
					} else if (attr.value.includes(ATTRIBUTE_MARKER_PREFIX)) {
						const attributeInfo = this.parseAttributeValue(attr.value);
						if (attributeInfo) {
							const isComposite = attributeInfo.indices.length > 1 || attributeInfo.strings.some((s) => s.length > 0);
							partPaths.push({
								path: [...path],
								type: 'attribute',
								index: attributeInfo.indices[0],
								name: attr.name,
								attributeStrings: isComposite ? attributeInfo.strings : undefined,
								attributeIndices: isComposite ? attributeInfo.indices : undefined
							});
						}
					}
				}
			}

			// Walk children
			const children = node.childNodes;
			for (let i = 0; i < children.length; i++) {
				path.push(i);
				walkTemplate(children[i], path);
				path.pop();
			}
		};

		walkTemplate(element.content, []);

		// Skip when an unsupported-position warning already named this template —
		// those bindings are lost too, and one diagnosis is enough.
		if (!hasUnsupportedBinding) {
			warnLeakedBindings(partPaths, this.strings.length - 1, html);
		}

		cached = { element, parts, partPaths };
		if (templateCache.size >= 500) {
			const oldestKey = templateCache.keys().next().value;
			if (oldestKey) {
				templateCache.delete(oldestKey);
			}
		}
		templateCache.set(key, cached);

		return cached;
	}

	/**
	 * Write a composite attribute (`class="card ${a} ${classMap(...)}"`).
	 *
	 * Static text and plain values are composed and written first; directive
	 * segments then run against the element, so an additive directive such as
	 * `classMap` layers on top of the static classes instead of replacing the
	 * whole attribute. Each directive segment keeps its own state, keyed by
	 * value index, because a composite attribute may hold several.
	 */
	private commitCompositeAttribute(part: ITemplatePart, element: Element): void {
		const name = part.name as string;
		const strings = part.attributeStrings as string[];
		const indices = part.attributeIndices as number[];

		let composed = strings[0] ?? '';
		const directiveSegments: Array<{ index: number; value: IDirectiveResultLike }> = [];

		for (let i = 0; i < indices.length; i++) {
			const segmentValue = this.values[indices[i]];

			if (isDirective(segmentValue)) {
				directiveSegments.push({ index: indices[i], value: segmentValue as IDirectiveResultLike });
				composed += strings[i + 1] ?? '';
			} else {
				composed += `${segmentValue ?? ''}${strings[i + 1] ?? ''}`;
			}
		}

		// Drop state for segments that stopped being directives.
		if (part.segmentDirectiveStates) {
			for (const [index, entry] of part.segmentDirectiveStates) {
				if (!directiveSegments.some((segment) => segment.index === index)) {
					disposeDirectiveState(entry.state);
					part.segmentDirectiveStates.delete(index);
				}
			}
		}

		const staticChanged = part.previousValue !== composed;

		if (staticChanged) {
			if (composed === '' && directiveSegments.length === 0 && strings.every((segment) => segment === '')) {
				element.removeAttribute(name);
			} else {
				element.setAttribute(name, composed);
			}

			part.previousValue = composed;

			// Rewriting the attribute wiped whatever the directives had applied,
			// so their "what did I add last time" state is now a lie.
			if (part.segmentDirectiveStates) {
				for (const entry of part.segmentDirectiveStates.values()) {
					disposeDirectiveState(entry.state);
				}
				part.segmentDirectiveStates.clear();
			}
		}

		if (directiveSegments.length === 0) {
			return;
		}

		const states = (part.segmentDirectiveStates ??= new Map());

		for (const segment of directiveSegments) {
			const existing = states.get(segment.index);

			if (existing && existing.type !== segment.value.type) {
				disposeDirectiveState(existing.state);
				states.delete(segment.index);
			}

			const state = segment.value.render(element, states.get(segment.index)?.state, name);
			states.set(segment.index, { state, type: segment.value.type });
		}
	}

	private getAttributePreProcessor(
		parts: ITemplatePart[]
	): Record<string, (index: number, html: string, attrName?: string, match?: RegExpExecArray | null) => string> {
		return {
			'@': (index: number, html: string, attrName?: string, match?: RegExpExecArray | null) => {
				// Event binding
				parts.push({
					type: 'event',
					index: index,
					name: attrName?.slice(1)
				});
				return html.slice(0, -(match?.[0].length ?? 0)) + `__event-${index}__=""`;
			},
			'.': (index: number, html: string, attrName?: string, match?: RegExpExecArray | null) => {
				// Property binding
				parts.push({
					type: 'property',
					index: index,
					name: attrName?.slice(1)
				});
				return html.slice(0, -(match?.[0].length ?? 0)) + `__prop-${index}__=""`;
			},
			':': (index: number, html: string, attrName?: string, match?: RegExpExecArray | null) => {
				// Action directive binding
				parts.push({
					type: 'action',
					index: index,
					name: attrName?.slice(1)
				});
				return html.slice(0, -(match?.[0].length ?? 0)) + `__action-${index}__=""`;
			},
			'?': (index: number, html: string, attrName?: string, match?: RegExpExecArray | null) => {
				// Boolean attribute binding
				parts.push({
					type: 'boolean-attribute',
					index: index,
					name: attrName?.slice(1)
				});
				return html.slice(0, -(match?.[0].length ?? 0)) + `__bool-${index}__=""`;
			},
			'__': (index: number, html: string, _?: string) => {
				// Regular attribute
				return html + createAttributeMarker(index);
			},
			'___': (index: number, html: string) => {
				// Text position
				parts.push({
					type: 'node',
					index: index
				});
				return html + COMMENT_NODE_MARKER;
			}
		};
	}

	private prepareParts(clone: Node, cache: ITemplateCache): ITemplatePart[] {
		const parts: ITemplatePart[] = [];
		const { partPaths } = cache;

		// Navigate directly to each part using pre-computed paths
		for (const partPath of partPaths) {
			// Navigate to the node using the path
			let node: Node = clone;
			for (const index of partPath.path) {
				node = node.childNodes[index];
			}

			if (partPath.type === 'node') {
				// Replace comment marker with text node
				const textNode = document.createTextNode('');
				node.parentNode!.replaceChild(textNode, node);

				parts.push({
					type: 'node',
					index: partPath.index,
					node: textNode
				});
			} else if (partPath.type === 'event') {
				const element = node as Element;
				element.removeAttribute(`__event-${partPath.index}__`);

				parts.push({
					type: 'event',
					index: partPath.index,
					name: partPath.name,
					node: element
				});
			} else if (partPath.type === 'property') {
				const element = node as Element;
				element.removeAttribute(`__prop-${partPath.index}__`);

				parts.push({
					type: 'property',
					index: partPath.index,
					name: partPath.name,
					node: element
				});
			} else if (partPath.type === 'action') {
				const element = node as Element;

				if (partPath.index >= 0) {
					element.removeAttribute(`__action-${partPath.index}__`);
				} else {
					// Static action directive
					element.removeAttribute(`:${partPath.name}`);
				}

				parts.push({
					type: 'action',
					index: partPath.index,
					name: partPath.name,
					node: element,
					staticValue: partPath.staticValue
				});
			} else if (partPath.type === 'boolean-attribute') {
				const element = node as Element;
				element.removeAttribute(`__bool-${partPath.index}__`);

				parts.push({
					type: 'boolean-attribute',
					index: partPath.index,
					name: partPath.name,
					node: element
				});
			} else if (partPath.type === 'attribute') {
				const element = node as Element;
				element.removeAttribute(partPath.name!);

				parts.push({
					type: 'attribute',
					index: partPath.index,
					name: partPath.name,
					node: element,
					attributeStrings: partPath.attributeStrings,
					attributeIndices: partPath.attributeIndices
				});
			}
		}

		return parts;
	}

	private parseAttributeValue(value: string): { strings: string[]; indices: number[] } | null {
		const strings: string[] = [];
		const indices: number[] = [];
		let lastIndex = 0;
		let match: RegExpExecArray | null;

		ATTRIBUTE_MARKER_REGEX.lastIndex = 0;
		while ((match = ATTRIBUTE_MARKER_REGEX.exec(value)) !== null) {
			strings.push(value.slice(lastIndex, match.index));
			indices.push(Number(match[1]));
			lastIndex = match.index + match[0].length;
		}

		if (indices.length === 0) {
			return null;
		}

		strings.push(value.slice(lastIndex));
		return { strings, indices };
	}

	/**
	 * Sets up markers for a node part to enable complex content rendering
	 */
	private ensureMarkers(part: ITemplatePart): void {
		if (part.startMarker) return; // Already set up

		const parent = part.node!.parentNode;
		if (!parent) return;

		const startMarker = document.createComment('part-start');
		const endMarker = document.createComment('part-end');

		parent.insertBefore(startMarker, part.node!);
		parent.insertBefore(endMarker, part.node!.nextSibling);

		part.startMarker = startMarker;
		part.endMarker = endMarker;
	}

	/**
	 * Clears the content a node part rendered between its markers, recursively
	 * disposing the nested part trees (directive/action cleanups) it owns.
	 *
	 * Disposal runs exactly once per container here; the DOM is then cleared as
	 * ONE live range walk from `startMarker` to `endMarker` (keeping `part.node`,
	 * the original text node the part renders plain values into). A snapshot of
	 * "the nodes this part inserted" cannot be trusted for that: a nested node
	 * part inside the rendered content swaps its own nodes whenever its template
	 * structure changes, and those replacements were never in the parent's list —
	 * so a snapshot-based teardown stranded them between the markers and the
	 * next render put a second copy beside the orphan.
	 */
	private clearRenderedNodes(part: ITemplatePart): void {
		// Dispose nested part trees BEFORE dropping the references, so cleanups
		// registered anywhere in the removed content actually run.
		if (part.nestedContainer) {
			disposeContainerParts(part.nestedContainer);
			part.nestedContainer = undefined;
		}

		if (part.renderedContainers) {
			for (const container of part.renderedContainers) {
				disposeContainerParts(container);
			}
			part.renderedContainers = undefined;
		}

		if (part.arrayState) {
			for (const item of part.arrayState.items) {
				disposeContainerParts(item.container);
			}
			part.arrayState = undefined;
		}

		if (part.positionalArrayState) {
			for (const item of part.positionalArrayState.items) {
				disposeContainerParts(item.container);
			}
			part.positionalArrayState = undefined;
		}

		if (part.startMarker && part.endMarker) {
			clearBetween(part.startMarker, part.endMarker, part.node);
		}
	}

	/**
	 * Clears DOM nodes created by a directive (e.g. repeat, when) when
	 * switching away from a directive to a different renderable type.
	 * Removes all nodes between the directive's markers and restores
	 * part.node into the DOM so non-directive rendering can proceed.
	 */
	private clearDirectiveDOM(part: ITemplatePart): void {
		const state = part.directiveState;
		if (!state) return;

		// Recursively dispose resources owned by the directive state (nested
		// part trees, subscriptions) before its DOM is removed.
		disposeDirectiveState(state);

		if (typeof state !== 'object') {
			part.directiveState = undefined;
			part.directiveType = undefined;
			return;
		}

		// Directive markers (repeat/when both use startMarker/endMarker)
		const { startMarker, endMarker } = state as IDirectiveState;

		if (startMarker && endMarker && startMarker.parentNode) {
			const parent = startMarker.parentNode;

			// Remove all nodes between markers (exclusive)
			let node = startMarker.nextSibling;
			while (node && node !== endMarker) {
				const next = node.nextSibling;
				parent.removeChild(node);
				node = next;
			}

			// Restore part.node before the end marker so non-directive
			// rendering has a valid text node to work with
			if (part.node) {
				parent.insertBefore(part.node, endMarker);
			}

			// Remove the directive markers themselves
			parent.removeChild(startMarker);
			parent.removeChild(endMarker);
		}

		part.directiveState = undefined;
		part.directiveType = undefined;
	}

	/**
	 * Renders a nested TemplateResult into a node part.
	 *
	 * Uses a persistent DocumentFragment container to enable in-place updates
	 * when the template structure hasn't changed (same tagged template literal).
	 * This follows the same pattern as the `when` directive — the fragment holds
	 * __parts/__templateKey after its children move to the real DOM, so subsequent
	 * renderInto() calls diff and update existing nodes instead of recreating them.
	 */
	private renderNestedTemplate(part: ITemplatePart, template: TemplateResult): void {
		this.ensureMarkers(part);

		// Reuse existing container for same template structure (avoids destroying/recreating DOM)
		if (part.nestedContainer) {
			const existingKey = (part.nestedContainer as RenderedContainer<DocumentFragment>).__templateKey;

			if (existingKey === getTemplateKey(template.strings)) {
				// Same structure — update existing DOM nodes in place
				template.renderInto(part.nestedContainer);
				return;
			}
		}

		// First render or template structure changed — clearRenderedNodes
		// recursively disposes the old nested part tree and clears the live
		// range between the markers before the new content goes in.
		this.clearRenderedNodes(part);
		part.node!.textContent = '';

		const container = document.createDocumentFragment();
		template.renderInto(container);
		part.nestedContainer = container;

		const parent = part.endMarker!.parentNode!;
		parent.insertBefore(container, part.endMarker!);
	}

	/**
	 * Renders a DOM Node into a node part
	 */
	private renderNode(part: ITemplatePart, node: Node): void {
		this.ensureMarkers(part);
		this.clearRenderedNodes(part);

		// Hide the original text node
		part.node!.textContent = '';

		const parent = part.endMarker!.parentNode!;
		parent.insertBefore(node, part.endMarker!);
	}

	/**
	 * Renders an array of values into a node part
	 */
	private renderArray(part: ITemplatePart, values: unknown[]): void {
		this.ensureMarkers(part);

		// Hide the original text node
		part.node!.textContent = '';

		const parent = part.endMarker!.parentNode!;
		const keyedValues = this.getKeyedValues(values);

		if (keyedValues) {
			// Entering keyed mode: whatever the part rendered before (an unkeyed
			// array, a nested template, a bare node) cannot be adopted by key, so
			// dispose and remove it before the keyed path takes over.
			if (!part.arrayState) {
				this.clearRenderedNodes(part);
			}

			const previousItems = part.arrayState?.items ?? [];

			// Old items bucketed by key. A bucket, not a single slot: with a
			// duplicated key the second entry used to reuse the item the first
			// had already claimed, so one value silently vanished from the DOM
			// and the surplus item was never disposed.
			const available = new Map<unknown, IKeyedArrayItem[]>();
			for (const item of previousItems) {
				const bucket = available.get(item.key);
				if (bucket) {
					bucket.push(item);
				} else {
					available.set(item.key, [item]);
				}
			}

			const seenKeys = new Set<unknown>();
			const nextItems: IKeyedArrayItem[] = [];

			for (const item of keyedValues) {
				if (seenKeys.has(item.key)) {
					devWarn(
						'array-duplicate-key',
						`An interpolated keyed array contains a duplicate key (${String(item.key)}). ` +
							'Keys must be unique — entries sharing a key cannot be tracked apart across renders.'
					);
				}
				seenKeys.add(item.key);

				const bucket = available.get(item.key);
				const existing = bucket?.shift();

				if (existing) {
					if (bucket!.length === 0) {
						available.delete(item.key);
					}
					this.updateArrayItem(existing, item.value);
					nextItems.push(existing);
				} else {
					const created = this.createArrayItem(item.value, parent, part.endMarker!);
					nextItems.push({ key: item.key, ...created });
				}
			}

			for (const bucket of available.values()) {
				for (const oldItem of bucket) {
					// Dispose the removed item's part tree, then remove its live
					// range (markers included) — not a snapshot of its nodes.
					disposeContainerParts(oldItem.container);
					removeRange(oldItem.start, oldItem.end);
				}
			}

			// Walk the items in their new order, moving each one's marker range in
			// front of the first node not yet placed. Items already in position
			// are skipped over without touching the DOM.
			let referenceNode: Node = this.firstArrayNode(part);
			for (const item of nextItems) {
				if (item.start === referenceNode) {
					referenceNode = item.end.nextSibling ?? part.endMarker!;
					continue;
				}
				moveRange(item.start, item.end, referenceNode);
			}

			part.arrayState = { items: nextItems };
			return;
		}

		warnPartiallyKeyedArray(part, values);
		this.renderPositionalArray(part, values, parent);
	}

	/**
	 * Renders a plain (unkeyed) array by reusing the previously rendered items
	 * positionally: index i of this render updates the nodes created for index i
	 * of the last one.
	 *
	 * Before this existed, every unkeyed array re-render tore its whole subtree
	 * down and rebuilt it. The output was always correct, but node identity was
	 * destroyed on every pass, and identity is load-bearing: the browser only
	 * fires `click` when mousedown and mouseup land on the SAME node, so a list
	 * inside a frequently re-rendering template could not be clicked at all.
	 * Focus, text selection, scroll position, `:hover`, CSS transitions and
	 * observer registrations were lost the same way.
	 *
	 * Reuse is by index only. Reordering an unkeyed array still churns nodes —
	 * `repeat(items, keyFn, template)` is the tool for that, and the dev-mode
	 * advisory below points at it when churn is actually observed.
	 */
	private renderPositionalArray(part: ITemplatePart, values: unknown[], parent: Node): void {
		const endMarker = part.endMarker!;

		// No positional state means the part held something else last render (a
		// nested template, a bare Node, a keyed array, text). Dispose and remove
		// it before taking ownership — clearRenderedNodes is a no-op when the
		// part is empty, so this also covers the first render.
		const isUpdate = part.positionalArrayState !== undefined;
		if (!isUpdate) {
			this.clearRenderedNodes(part);
		}

		const state = part.positionalArrayState ?? { items: [] };
		const items = state.items;
		let recreated = 0;

		for (let index = 0; index < values.length; index++) {
			const value = values[index];
			const existing = items[index];

			if (existing) {
				// A rebuilt item lands between its own markers, so it stays at
				// this index without needing an insertion anchor.
				if (this.updateArrayItem(existing, value)) {
					recreated++;
				}
			} else {
				// The array grew — new items append before the end marker.
				items[index] = this.createArrayItem(value, parent, endMarker);
			}
		}

		// The array shrank — dispose the tail's part trees (so cleanups nested
		// anywhere inside them run) before dropping their live ranges.
		if (items.length > values.length) {
			for (const removed of items.splice(values.length)) {
				disposeContainerParts(removed.container);
				removeRange(removed.start, removed.end);
			}
		}

		part.positionalArrayState = state;

		if (isUpdate) {
			warnUnkeyedArrayChurn(state, recreated, values.length);
		}
	}

	/**
	 * The first node of an array part's item area: the sibling after the part's
	 * (emptied) text node, which sits directly after the start marker. Falls
	 * back to the node after the start marker if the text node is not there.
	 */
	private firstArrayNode(part: ITemplatePart): Node {
		const textNode = part.node;
		if (textNode && textNode.parentNode === part.startMarker!.parentNode && textNode.nextSibling) {
			return textNode.nextSibling;
		}
		return part.startMarker!.nextSibling ?? part.endMarker!;
	}

	private getKeyedValues(values: unknown[]): Array<{ key: unknown; value: unknown }> | null {
		if (values.length === 0) {
			return null;
		}

		const keyedValues: Array<{ key: unknown; value: unknown }> = [];
		for (const value of values) {
			if (value && typeof value === 'object' && (value as { __keyed?: boolean }).__keyed === true) {
				const keyed = value as { key: unknown; value: unknown };
				keyedValues.push({ key: keyed.key, value: keyed.value });
			} else {
				return null;
			}
		}

		return keyedValues;
	}

	/**
	 * Renders one array item into a fresh container and inserts it, wrapped in
	 * its own marker pair, before `endMarker`. Every later removal, move or
	 * rebuild of the item walks the live range between those markers — the
	 * same pattern `repeat()` uses — so nodes a nested part swaps in later are
	 * never stranded.
	 */
	private createArrayItem(value: unknown, parent: Node, endMarker: Comment): IArrayItem {
		const container = document.createDocumentFragment();
		this.renderArrayItemValue(value, container);

		const start = document.createComment('item-start');
		const end = document.createComment('item-end');
		parent.insertBefore(start, endMarker);
		parent.insertBefore(container, endMarker);
		parent.insertBefore(end, endMarker);
		return { value, container, start, end };
	}

	private renderArrayItemValue(value: unknown, container: DocumentFragment): void {
		if (value instanceof TemplateResult) {
			value.renderInto(container);
		} else if (value instanceof Node) {
			container.appendChild(value);
		} else if (value !== null && value !== undefined) {
			container.appendChild(document.createTextNode(String(value)));
		}
	}

	/**
	 * Updates one array item in place where possible. A rebuilt item replaces
	 * whatever currently lies between its own markers, so it keeps its position
	 * in both the keyed and positional paths.
	 *
	 * @returns true when the item's live nodes were replaced (its DOM identity
	 * did not survive), false when the existing nodes were updated in place.
	 */
	private updateArrayItem(item: IArrayItem, value: unknown): boolean {
		// A container only carries a part tree when a TemplateResult was rendered
		// into it. Without one there is nothing to update in place — the item
		// currently holds a bare Node or a text node — so a template value has to
		// go down the rebuild path below rather than through renderDetachedItem
		// (which would leave the new nodes stranded in the detached fragment).
		const hasPartTree = (item.container as RenderedContainer<DocumentFragment>).__parts !== undefined;

		if (value instanceof TemplateResult && hasPartTree) {
			// renderDetachedItem updates the live nodes in place when the
			// structure is unchanged, and otherwise replaces the item's whole
			// marker range with the rebuilt nodes.
			const replaced = renderDetachedItem(value, item.container, item.start, item.end);
			item.value = value;
			return replaced;
		}

		if (!(value instanceof TemplateResult) && value === item.value) {
			return false;
		}

		// Primitive → primitive at the same position: retarget the existing text
		// node instead of replacing it, so its identity survives too.
		const only = item.start.nextSibling;
		if (
			!(value instanceof TemplateResult) &&
			!(value instanceof Node) &&
			value !== null &&
			value !== undefined &&
			!hasPartTree &&
			only !== null &&
			only.nextSibling === item.end &&
			only.nodeType === Node.TEXT_NODE
		) {
			only.nodeValue = String(value);
			item.value = value;
			return false;
		}

		// The item's content type changed (e.g. was a template, now a plain
		// value) — dispose the old part tree, then replace the item's live range.
		disposeContainerParts(item.container);
		clearBetween(item.start, item.end);

		item.container = document.createDocumentFragment();
		this.renderArrayItemValue(value, item.container);
		item.end.parentNode?.insertBefore(item.container, item.end);
		item.value = value;
		return true;
	}

	/**
	 * Commits an event binding through a stable wrapper listener.
	 *
	 * The wrapper is created once per part and registered with a single
	 * addEventListener call; subsequent renders only swap the stored handler,
	 * so re-renders cause zero add/removeEventListener churn and the listener
	 * keeps its original position in the target's listener list.
	 *
	 * Accepted values: a plain function (invoked with `this` = the event's
	 * currentTarget, matching direct addEventListener semantics) or an object
	 * with `handleEvent` plus optional listener options (capture/once/passive —
	 * see IEventHandlerWithOptions). When the options change, the wrapper is
	 * re-attached with the new options. Removal on part disposal is handled by
	 * disposePart (dispose.functions.ts).
	 */
	private commitEventPart(part: ITemplatePart, value: unknown): void {
		const element = part.node as Element;
		const name = part.name as string;

		const isFunctionHandler = typeof value === 'function';
		const isHandleEventObject =
			!isFunctionHandler &&
			value !== null &&
			typeof value === 'object' &&
			typeof (value as EventListenerObject).handleEvent === 'function';
		const active = isFunctionHandler || isHandleEventObject;
		const newOptions = isHandleEventObject ? extractListenerOptions(value as IEventHandlerWithOptions) : undefined;

		// One stable wrapper per event part, created lazily on the first
		// non-empty handler and kept for the part's lifetime.
		if (!part.eventWrapper) {
			part.eventWrapper = function (this: Element, event: Event): void {
				const handler = part.eventHandler;
				if (typeof handler === 'function') {
					// Preserve direct-listener semantics: `this` is the currentTarget.
					(handler as EventListener).call(this, event);
				} else if (handler !== null && typeof handler === 'object') {
					// EventListenerObject semantics: `this` is the handler object.
					(handler as EventListenerObject).handleEvent(event);
				}
			};
		}

		const optionsChanged = !sameListenerOptions(part.eventOptions, newOptions);

		if (part.eventAttached && (!active || optionsChanged)) {
			element.removeEventListener(name, part.eventWrapper, part.eventOptions);
			part.eventAttached = false;
		}

		part.eventHandler = active ? value : undefined;
		part.eventOptions = newOptions;

		// `once` listeners are re-armed when the handler changes: if the previous
		// registration already fired (and was auto-removed) this re-attaches; if
		// it hasn't fired yet, registering the identical wrapper + options is a
		// spec-guaranteed no-op, so `once` semantics are preserved either way.
		if (active && (!part.eventAttached || newOptions?.once)) {
			element.addEventListener(name, part.eventWrapper, newOptions);
			part.eventAttached = true;
		}
	}

	private commit(parts: ITemplatePart[]): void {
		for (const part of parts) {
			const value = this.values[part.index];
			const isCompositeAttribute = part.type === 'attribute' && part.attributeIndices && part.attributeStrings;

			// Skip unchanged values (but not for directives or action parts - they manage their own state)
			// Action parts with index < 0 are static and have their own skip logic
			if (!isCompositeAttribute && !isDirective(value) && part.type !== 'action' && part.previousValue === value) {
				continue;
			}

			switch (part.type) {
				case 'node':
					if (part.node) {
						const wasDirective = isDirective(part.previousValue);
						const nowDirective = isDirective(value);

						// Transition from directive → non-directive: clean up directive DOM
						if (wasDirective && !nowDirective && part.directiveState) {
							this.clearDirectiveDOM(part);
						}

						// Transition from non-directive → directive: clean up rendered nodes
						if (!wasDirective && nowDirective) {
							this.clearRenderedNodes(part);
						}

						// Handle directives
						if (nowDirective) {
							// Transition between two DIFFERENT directive types: never hand
							// one directive's state to another. Dispose the old directive's
							// state and DOM, then let the new directive start fresh.
							if (part.directiveState !== undefined && part.directiveType !== value.type) {
								this.clearDirectiveDOM(part);
							}
							part.directiveState = value.render(part.node, part.directiveState);
							part.directiveType = value.type;
						} else if (value instanceof TemplateResult) {
							// Handle nested TemplateResult
							this.renderNestedTemplate(part, value);
						} else if (value instanceof Node) {
							// Handle DOM Node
							this.renderNode(part, value);
						} else if (Array.isArray(value)) {
							// Handle arrays of values
							this.renderArray(part, value);
						} else {
							// Clear any previously rendered complex content
							this.clearRenderedNodes(part);
							part.node.textContent = String(value ?? '');
						}
					}
					break;

				case 'attribute':
					if (part.node && part.name) {
						const element = part.node as Element;

						// A composite attribute is handled as a whole — including when
						// one of its segments is a directive. Checking `isDirective`
						// first (as this used to) rendered the directive and dropped
						// every static segment: `class="card ${classMap({active})}"`
						// produced `class="active"`.
						if (isCompositeAttribute) {
							this.commitCompositeAttribute(part, element);
							continue;
						}

						// Leaving a directive for a plain value: run its cleanup now,
						// not whenever another directive happens to replace it.
						if (!isDirective(value) && part.directiveState !== undefined) {
							disposeDirectiveState(part.directiveState);
							part.directiveState = undefined;
							part.directiveType = undefined;
						}

						// Handle directives
						if (isDirective(value)) {
							if (part.directiveState !== undefined && part.directiveType !== value.type) {
								// Directive type switched — dispose the old state instead of
								// passing it to a different directive.
								disposeDirectiveState(part.directiveState);
								part.directiveState = undefined;
							}
							part.directiveState = value.render(element, part.directiveState, part.name);
							part.directiveType = value.type;
						} else if (typeof value === 'boolean' && part.name.startsWith('aria-')) {
							// ARIA state attributes use the literal strings "true"/"false",
							// never HTML boolean-attribute (present/absent) semantics.
							element.setAttribute(part.name, String(value));
						} else if (value === null || value === undefined || value === false) {
							// Remove attribute for null, undefined, or false (boolean attributes)
							element.removeAttribute(part.name);
						} else if (value === true) {
							// Boolean true sets empty attribute (e.g., disabled="")
							element.setAttribute(part.name, '');
						} else {
							element.setAttribute(part.name, String(value));
						}
					}
					break;

				case 'boolean-attribute':
					if (part.node && part.name) {
						const element = part.node as Element;
						if (value) {
							element.setAttribute(part.name, '');
						} else {
							element.removeAttribute(part.name);
						}
					}
					break;

				case 'property':
					if (part.node && part.name) {
						if (!isDirective(value) && part.directiveState !== undefined) {
							disposeDirectiveState(part.directiveState);
							part.directiveState = undefined;
							part.directiveType = undefined;
						}

						// Handle directives
						if (isDirective(value)) {
							if (part.directiveState !== undefined && part.directiveType !== value.type) {
								disposeDirectiveState(part.directiveState);
								part.directiveState = undefined;
							}
							part.directiveState = value.render(part.node as Element, part.directiveState, part.name);
							part.directiveType = value.type;
						} else {
							if (part.name === 'innerHTML' || part.name === 'outerHTML') {
								warnUnsafePropertyBinding(part.name);
							}
							(part.node as Element & Record<string, unknown>)[part.name] = value;
						}
					}
					break;

				case 'event':
					if (part.node && part.name) {
						this.commitEventPart(part, value);
					}
					break;

				case 'action':
					if (part.node && part.name) {
						const element = part.node as Element;

						// Get directive value: dynamic (from values array) or static (from attribute)
						const directiveValue = part.index >= 0 ? value : part.staticValue;

						// Skip if value hasn't changed (for dynamic values)
						if (part.index >= 0 && part.previousValue === directiveValue) {
							continue;
						}

						// For static directives, only run once (when actionCleanup is undefined)
						if (part.index < 0 && part.actionCleanup !== undefined) {
							continue;
						}

						// Call previous cleanup if exists
						if (part.actionCleanup) {
							part.actionCleanup();
							part.actionCleanup = undefined;
						}

						// Look up directive from registry
						const directive = getAttributeDirective(part.name);
						if (directive) {
							const cleanup = directive(element, directiveValue, part.name);
							if (typeof cleanup === 'function') {
								part.actionCleanup = cleanup;
							} else {
								// Mark as initialized even without cleanup
								part.actionCleanup = () => {};
							}
						} else {
							console.warn(`Attribute directive ':${part.name}' not found in registry`);
						}
					}
					break;
				default:
					break;
			}

			part.previousValue = value;
		}
	}
}
